/// A typed `/info` option: one named constructor per option of the catalogue.
///
/// `InfoOption.size(true)`, `InfoOption.blurhash(4, 3)`.
final class InfoOption extends OptionValue {
  const InfoOption._(super.name, super.args) : super._();

