  ///
  /// - `quality`: 1..100; 0 = default. Range ≥ 0, ≤ 100.
  VideoOption.quality(int quality) : this._('quality', [quality]);

  /// Stream the source without processing.
  ///
  /// URL names: `raw`; arguments `bool`; default false. Milestone M1; scope request.
  ///
  /// - `raw`: stream the source unprocessed. Null writes an empty argument.
  VideoOption.raw(bool? raw) : this._('raw', [raw]);

  /// Resize like imgproxy: fit (scale-down, or contain with enlarge; extend pads), fill and fill-down (cover, cropped by gravity), force (stretch).
  ///
  /// URL names: `resize`, `rs`; arguments `type:w:h:enlarge:extend`; default fit:0:0:false:false. Milestone M5 (WP-122); scope request.
  ///
  /// - `type`: resizing type. One of `fit`, `fill`, `fill-down`, `force`. Null writes an empty argument.
  /// - `width`: output width in pixels; 0 keeps the aspect ratio. Range ≥ 0, ≤ 8192. Null writes an empty argument.
  /// - `height`: output height in pixels; 0 keeps the aspect ratio. Range ≥ 0, ≤ 8192. Null writes an empty argument.
  /// - `enlarge`: fit may enlarge. Null writes an empty argument.
  /// - `extend`: pad to the box with the background. Null writes an empty argument.
  VideoOption.resize(String? type, [int? width, int? height, bool? enlarge, bool? extend]) : this._('resize', trimArgs([type, width, height, enlarge, extend], 1));

  /// Resizing type (auto is not available for video).
  ///
  /// URL names: `resizing_type`, `rt`; arguments `fit, fill, fill-down, force`; default fit. Milestone M5 (WP-122); scope request.
  ///
  /// - `type`: resizing type. One of `fit`, `fill`, `fill-down`, `force`.
  VideoOption.resizingType(String type) : this._('resizing_type', [type]);

  /// Download instead of inline display.
  ///
  /// URL names: `return_attachment`, `att`; arguments `bool`; default config. Milestone M1; scope request.
  ///
  /// - `attachment`: Content-Disposition: attachment. Null writes an empty argument.
  VideoOption.returnAttachment(bool? attachment) : this._('return_attachment', [attachment]);

  /// Rotate clockwise after the display matrix.
  ///
  /// URL names: `rotate`, `rot`; arguments `multiple of 90`; default 0. Milestone M5 (WP-122); scope request.
  ///
  /// - `angle`: clockwise degrees, a multiple of 90.
  VideoOption.rotate(int angle) : this._('rotate', [angle]);

  /// Output sample rate (the codec must support it: Opus 8/12/16/24/48 kHz).
  ///
  /// URL names: `sample_rate`, `sr`; arguments `Hz`; default source. Milestone M5 (WP-123); scope request.
  ///
  /// - `hz`: 8000, 11025, 12000, 16000, 22050, 24000, 32000, 44100, 48000, 88200 or 96000. Range ≥ 0, ≤ 96000.
  VideoOption.sampleRate(int hz) : this._('sample_rate', [hz]);

  /// Length of a stream's segments (1..30 s).
  ///
  /// URL names: `segment_duration`, `sgd`; arguments `seconds`; default XI_VIDEO_TRANSFORM_SEGMENT_DURATION (6). Milestone M5 (WP-126); scope request.
  ///
  /// - `seconds`: whole seconds. Range ≥ 1, ≤ 30.
  VideoOption.segmentDuration(int seconds) : this._('segment_duration', [seconds]);

  /// Container of a stream's segments: fmp4 (CMAF, HLS 7 and DASH) or ts (MPEG-TS for older HLS players: HLS only, H.264 and AAC muxed in each segment; images with libx264 only).
  ///
  /// URL names: `segment_format`, `sgf`; arguments `format`; default fmp4. Milestone M5 (WP-131); scope request.
  ///
  /// - `format`: CMAF (fragmented MP4: fmp4, cmaf) or MPEG-TS (ts, mpegts). One of `cmaf`, `fmp4`, `mpegts`, `ts`.
  VideoOption.segmentFormat(String format) : this._('segment_format', [format]);

  /// Resize without the type.
  ///
  /// URL names: `size`, `s`; arguments `w:h:enlarge:extend`; default 0:0:false:false. Milestone M5 (WP-122); scope request.
  ///
  /// - `width`: output width in pixels; 0 keeps the aspect ratio. Range ≥ 0, ≤ 8192. Null writes an empty argument.
  /// - `height`: output height in pixels; 0 keeps the aspect ratio. Range ≥ 0, ≤ 8192. Null writes an empty argument.
  /// - `enlarge`: fit may enlarge. Null writes an empty argument.
  /// - `extend`: pad to the box with the background. Null writes an empty argument.
  VideoOption.size(int? width, [int? height, bool? enlarge, bool? extend]) : this._('size', trimArgs([width, height, enlarge, extend], 1));

  /// Start the output at this time of the source (exact, from the keyframe before it).
  ///
  /// URL names: `start`, `vs`; arguments `seconds`; default 0. Milestone M5 (WP-122); scope request.
  ///
  /// - `seconds`: start of the output in the source. Range ≥ 0, ≤ 86400.
  VideoOption.start(num seconds) : this._('start', [seconds]);

  /// Deliver an HLS or DASH stream (as the m3u8 or mpd extension does) with these renditions (at most 8; none: the configured ladder). Rungs above the source are dropped.
  ///
  /// URL names: `stream`, `st`; arguments `protocol:height…`; default none (a file). Milestone M5 (WP-126); scope request.
  ///
  /// - `protocol`: manifest: HLS (m3u8) or DASH (mpd). One of `dash`, `hls`.
  /// - `heights`: Repeated argument: `height`: a rendition by the short side of its frame. Range ≥ 64, ≤ 4320. Null writes an empty argument.
  VideoOption.stream(String protocol, [List<int> heights = const []]) : this._('stream', [protocol, ...heights]);

  /// Draw the output's running time (FFmpeg drawtext with a fixed expansion).
  ///
  /// URL names: `timecode`, `tc`; arguments `format:position:x:y:size:color:opacity`; default none:sowe:0:0:0:ffffff:1. Milestone M5 (WP-124); scope request.
  ///
  /// - `format`: HH:MM:SS.mmm, seconds, or none. One of `hms`, `seconds`, `none`.
  /// - `position`: compass position. One of `ce`, `no`, `so`, `ea`, `we`, `noea`, `nowe`, `soea`, `sowe`. Null writes an empty argument.
  /// - `xOffset`: offset in pixels. Null writes an empty argument.
  /// - `yOffset`: offset in pixels. Null writes an empty argument.
  /// - `size`: font size in pixels; 0 = default. Range ≥ 0, ≤ 512. Null writes an empty argument.
  /// - `color`: text colour (white). A hex colour (`ff0000`, `f00`, with optional alpha). Null writes an empty argument.
  /// - `opacity`: opacity (1). Range ≥ 0, ≤ 1. Null writes an empty argument.
  VideoOption.timecode(String format, [String? position, num? xOffset, num? yOffset, int? size, String? color, num? opacity]) : this._('timecode', trimArgs([format, position, xOffset, yOffset, size, color, opacity], 1));

  /// Cap the video bit rate (50k..200M).
  ///
  /// URL names: `video_bitrate`, `vb`; arguments `bit/s (k, M)`; default uncapped. Milestone M5 (WP-122); scope request.
  ///
  /// - `bitrate`: bits per second, k or M suffix.
  VideoOption.videoBitrate(String bitrate) : this._('video_bitrate', [bitrate]);

  /// Video codec (h264 and hevc need the gpl image).
  ///
  /// URL names: `video_codec`, `vc`; arguments `auto, h264, av1, vp9, hevc`; default auto. Milestone M5 (WP-122); scope request.
  ///
  /// - `codec`: video codec. One of `auto`, `av1`, `h264`, `h265`, `hevc`, `vp9`.
  VideoOption.videoCodec(String codec) : this._('video_codec', [codec]);

  /// Change the audio level (-60 dB..+20 dB).
  ///
  /// URL names: `volume`, `vol`; arguments `factor or NdB`; default 1. Milestone M5 (WP-123); scope request.
  ///
  /// - `gain`: a factor (0.5) or decibels (-6dB).
  VideoOption.volume(String gain) : this._('volume', [gain]);

  /// Draw the watermark.
  ///
  /// URL names: `watermark`, `wm`; arguments `opacity:pos:x:y:scale; pos incl. `re` (tile), `ch` (chessboard, Pro)`; default off. Milestone M1 (`re` M1, `ch` M3 WP-77); scope pipeline.
  ///
  /// - `opacity`: opacity (0..1); 0 disables. Range ≥ 0, ≤ 1.
  /// - `position`: compass position, re (tile) or ch (chessboard). One of `ce`, `no`, `so`, `ea`, `we`, `noea`, `nowe`, `soea`, `sowe`, `re`, `ch`. Null writes an empty argument.
  /// - `xOffset`: x offset. Null writes an empty argument.
  /// - `yOffset`: y offset. Null writes an empty argument.
  /// - `scale`: scale relative to the image. Range &gt; 0. Null writes an empty argument.
  VideoOption.watermark(num opacity, [String? position, num? xOffset, num? yOffset, num? scale]) : this._('watermark', trimArgs([opacity, position, xOffset, yOffset, scale], 1));

  /// Watermark rotation, clockwise.
  ///
  /// URL names: `watermark_rotate`, `wm_rot`, `wmr`; arguments `degrees`; default 0. Milestone M3 (WP-77); scope pipeline. imgproxy Pro option (free here).
  ///
  /// - `angle`: degrees.
  VideoOption.watermarkRotate(num angle) : this._('watermark_rotate', [angle]);

  /// Watermark shadow: its alpha blurred with sigma, in black.
  ///
  /// URL names: `watermark_shadow`, `wmsh`; arguments `sigma`; default off. Milestone M3 (WP-77); scope pipeline. imgproxy Pro option (free here).
  ///
  /// - `sigma`: shadow blur sigma. Range ≥ 0, ≤ 1000.
  VideoOption.watermarkShadow(num sigma) : this._('watermark_shadow', [sigma]);

  /// Watermark size in pixels (fit, enlarging; used when the wm scale is 0).
  ///
  /// URL names: `watermark_size`, `wms`; arguments `w:h`; default 0:0. Milestone M3 (WP-77); scope pipeline. imgproxy Pro option (free here).
  ///
  /// - `width`: width; 0 = auto. Range ≥ 0, ≤ 65536. Null writes an empty argument.
  /// - `height`: height; 0 = auto. Range ≥ 0, ≤ 65536. Null writes an empty argument.
  VideoOption.watermarkSize(int? width, [int? height]) : this._('watermark_size', trimArgs([width, height], 1));

  /// Text watermark (replaces watermark_url); markup is sanitised to a whitelist, font `sans 16` by default.
  ///
  /// URL names: `watermark_text`, `wmt`; arguments `base64url Pango markup`; default —. Milestone M3 (WP-78); scope pipeline. imgproxy Pro option (free here).
  ///
  /// - `text`: url-safe base64 of Pango markup. URL-safe base64, written as given. Null writes an empty argument.
  VideoOption.watermarkText(String? text) : this._('watermark_text', [text]);

  /// Watermark image source, fetched like a source (allowlist, SSRF policy, byte limit, origin cache).
  ///
  /// URL names: `watermark_url`, `wmu`; arguments `base64url URL`; default config image. Milestone M3 (WP-77); scope pipeline. imgproxy Pro option (free here).
  ///
  /// - `url`: url-safe base64 of the watermark source URL; empty = configured image. URL-safe base64, written as given. Null writes an empty argument.
  VideoOption.watermarkUrl(String? url) : this._('watermark_url', [url]);

  /// Render the audio as a width × height (default 1024×256) PNG or WebP picture.
  ///
  /// URL names: `waveform`, `wf`; arguments `enabled:color:background:split`; default false:000000::false. Milestone M5 (WP-123); scope request.
  ///
  /// - `enabled`: render a waveform picture. Null writes an empty argument.
  /// - `color`: wave colour. A hex colour (`ff0000`, `f00`, with optional alpha). Null writes an empty argument.
  /// - `background`: background colour; empty is transparent. A hex colour (`ff0000`, `f00`, with optional alpha). Null writes an empty argument.
  /// - `splitChannels`: one band per channel. Null writes an empty argument.
  VideoOption.waveform(bool? enabled, [String? color, String? background, bool? splitChannels]) : this._('waveform', trimArgs([enabled, color, background, splitChannels], 1));

  /// Output width (rounded down to even).
  ///
  /// URL names: `width`, `w`; arguments `px`; default 0. Milestone M5 (WP-122); scope request.
  ///
  /// - `width`: pixels. Range ≥ 0, ≤ 8192.
  VideoOption.width(int width) : this._('width', [width]);
}
